-- ==========================================================================
-- B4 FOLLOW-ON FIX (earthmodel): earthmodel: one distractor that printed the correct easting
--
-- Courses: earthmodel. Rows changed: 1; rows inserted: 0.
-- Source: tools/answer-length-audit/fixes/earthmodel.json (every item, its verdict and
-- its reason, old and new text side by side); generated by
-- tools/answer-length-audit/fix.py sql earthmodel. Runs AFTER the 29 B4 length files
-- and any earlier fix file: every guard below is the text those leave behind.
--
-- GUARDS. Each changed row must match its OLD prompt, explanation and options
-- (md5) and answer_index exactly (then it is updated) or its NEW ones (already
-- applied, left alone). Anything else raises and the transaction rolls back.
-- Each insert must be absent (inserted) or present with the same text (left).
-- Each course ends at its asserted question count. SAFE TO RE-RUN.
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_total   integer;
begin

  -- earthmodel intermediate module m02-minimum-curvature ord 13
  select case when md5(prompt) = '90c5d3289a5d740762470abfa0f78b8a' and md5(coalesce(explanation, '')) = 'e9af34c5687d27acfb4e5afdde880690' and md5(options::text) = md5('["x 1794.719681048036, adding the 300 m hold length as easting.", "x 1900, matching its measured depth.", "x 1794.719681048036, adding 282.84271247461896 m of easting in the hold.", "x 1683.753937146834, adding a second build increment of easting."]'::jsonb::text) and answer_index = 2 then 'old'
              when md5(prompt) = '90c5d3289a5d740762470abfa0f78b8a' and md5(coalesce(explanation, '')) = '340976897b9a95cb270053b8fe30d652' and md5(options::text) = md5('["x 1752.9376073217509, the TVD column read as easting.", "x 1900, matching its measured depth.", "x 1794.719681048036, adding 282.84271247461896 m of easting in the hold.", "x 1683.753937146834, adding a second build increment of easting."]'::jsonb::text) and answer_index = 2 then 'new'
              else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'earthmodel' and tier = 'intermediate' and scope = 'module' and module_key is not distinct from 'm02-minimum-curvature' and ord = 13 and active;
  if v_state is null then raise exception 'B4 fix earthmodel refused: no row for earthmodel intermediate module m02-minimum-curvature ord 13'; end if;
  if v_state = 'other' then raise exception 'B4 fix earthmodel refused: earthmodel intermediate module m02-minimum-curvature ord 13 matches neither its current nor its fixed form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'Station 1500 lands at x 1511.876968573417. Where does station 1900 land?', options = '["x 1752.9376073217509, the TVD column read as easting.", "x 1900, matching its measured depth.", "x 1794.719681048036, adding 282.84271247461896 m of easting in the hold.", "x 1683.753937146834, adding a second build increment of easting."]'::jsonb,
           answer_index = 2, explanation = 'The 400 m hold contributes 400/sqrt 2 = 282.84 m east. Reading the TVD column as easting, doubling the build increment or equating x with MD are all real mistakes the numbers punish.'
     where app_slug = 'earthmodel' and tier = 'intermediate' and scope = 'module' and module_key is not distinct from 'm02-minimum-curvature' and ord = 13 and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B4 fix earthmodel refused: earthmodel intermediate module m02-minimum-curvature ord 13 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'earthmodel' and active;
  if v_total <> 396 then raise exception 'B4 fix earthmodel refused: earthmodel holds % active questions, expected 396', v_total; end if;
  raise notice 'B4 fix earthmodel: % of 1 rows written, the rest already carried the fixed text', v_updated;
end $$;
